    if ($Spec.Adapter -eq 'MachineEnvironment' -and $Spec.Desired.Name -match '^(?i)(?:PATH|SystemRoot|windir|COMSPEC|TEMP|TMP|PROCESSOR.*|NUMBER_OF_PROCESSORS)$') { throw 'Shared OS environment variables require dedicated reviewed procedure.' }
    if($Spec.Adapter -eq 'MachineEnvironment' -and $Spec.Desired.Name -ieq 'LOCAL' -and ([string]$Spec.Desired.Value).Length -gt 0){throw 'Nonempty Oracle LOCAL requires external credential-safe handling.'}
    if($Spec.PSObject.Properties['SettingTransition']) {
        Assert-WsmSettingTransition $Spec.SettingTransition | Out-Null
        if($Spec.SettingTransition.Adapter -cne $Spec.Adapter){throw 'SettingTransition adapter must match MigrationSpec.Adapter.'}
        if($Spec.Adapter -in @('MachineEnvironment','TimeZone') -and ($Spec.SettingTransition.Name -cne $Spec.Desired.Name -or [string]$Spec.SettingTransition.After.Value -cne [string]$Spec.Desired.Value)){throw 'Desired state must match the reviewed SettingTransition after value.'}
    }
    if($Spec.Adapter -eq 'TimeZone') { if(-not $Spec.PSObject.Properties['SettingTransition'] -or $Spec.Desired.Name -cne 'TimeZone' -or $Spec.SettingTransition.Adapter -cne 'TimeZone'){throw 'TimeZone requires a typed SettingTransition and the finite TimeZone identity.'} }
    if($Spec.Adapter -eq 'Service'){[void](Assert-WsmServiceSupplement $Spec.Desired.Supplement);$policy=Get-WsmServiceAccountPolicy $Spec.Desired $Spec;if($policy.Mode -ceq 'ReviewRequired'){throw 'Service account mode must be reviewed before migration approval.'};[void](ConvertTo-WsmServiceDependencyMultiSz @($Spec.Desired.Dependencies))};if($Spec.Adapter -eq 'SmbShare' -and ($Spec.Desired.DrainPolicy -cnotin @('BlockNewOpens','CloseReviewedHandles') -or [string]::IsNullOrWhiteSpace($Spec.Desired.DrainEvidence))){throw 'SMB share requires reviewed drain policy and evidence.'};if($Spec.Adapter -eq 'WindowsFeature'){Assert-WsmInstallerPolicy $Spec.Desired}
    $needsSecret=$Spec.Adapter -eq 'LocalUser' -or ($Spec.Adapter -eq 'Certificate' -and $Spec.Desired.HasPrivateKey) -or ($Spec.Adapter -eq 'Service' -and (Get-WsmServiceAccountPolicy $Spec.Desired $Spec).NeededSecret)
    if($Spec.Adapter -eq 'ScheduledTask'){$principal=(Read-WsmXml $Spec.Desired.Xml).SelectSingleNode("//*[local-name()='Principal']/*[local-name()='LogonType']");if($principal -and $principal.InnerText -eq 'Password'){$needsSecret=$true}}
    if($needsSecret -and (-not $Spec.PSObject.Properties['SecretRef'] -or -not $Spec.SecretRef)){throw 'Adapter requires a reviewed SecretRef; no passwords may be stored in desired configuration.'}
}
function Get-WsmAdapterRequiredCommands([string]$Adapter) {
    switch ($Adapter) {
        ScheduledTask { @('Get-ScheduledTask','Register-ScheduledTask','Export-ScheduledTask','Unregister-ScheduledTask') }
        Service { @('Get-Service','New-Service','Set-Service') }
        SmbShare { @('Get-SmbShare','New-SmbShare','Get-SmbShareAccess','Grant-SmbShareAccess','Block-SmbShareAccess') }
        TimeZone { @('Get-TimeZone','Set-TimeZone') }
        WindowsFeature { @('Get-WindowsFeature','Install-WindowsFeature') }
        LocalUser { @('Get-LocalUser','New-LocalUser','Disable-LocalUser') }
        LocalGroup { @('Get-LocalGroup','New-LocalGroup','Add-LocalGroupMember') }
        FirewallRule { @('Get-NetFirewallRule','New-NetFirewallRule') }
        Certificate { @('Get-PfxData','Import-PfxCertificate','Import-Certificate') }
        { $_ -in @('IISPool','IISSite') } { @('Get-WebConfiguration') }
        default { @() }
    }
}
function Get-WsmEveryoneName {(New-Object Security.Principal.SecurityIdentifier('S-1-1-0')).Translate([Security.Principal.NTAccount]).Value}
function ConvertTo-WsmShareAclKeys([object[]]$Access) {
    foreach($ace in $Access){(Resolve-WsmAccountSid ([string]$ace.AccountName))+'|'+[string]$ace.AccessControlType+'|'+[string]$ace.AccessRight}
}
function Test-WsmDesiredWorldDeny($Desired) {
    foreach($ace in $Desired.Access){if($ace.AccessControlType -eq 'Deny' -and (Resolve-WsmAccountSid ([string]$ace.AccountName)) -eq 'S-1-1-0'){return $true}};$false
}
function Get-WsmSecret($Spec,[hashtable]$Secrets) {
    if (-not $Spec.PSObject.Properties['SecretRef'] -or -not $Spec.SecretRef) { return $null }
    if (-not $Secrets -or -not $Secrets.ContainsKey($Spec.SecretRef) -or $Secrets[$Spec.SecretRef] -isnot [Management.Automation.PSCredential]) { throw ('Required in-memory credential unavailable: '+$Spec.SecretRef) }
    $Secrets[$Spec.SecretRef]
}
function New-WsmTaskScheduler {$scheduler=New-Object -ComObject 'Schedule.Service';$scheduler.Connect();$scheduler}
function Test-WsmKnownAdapterAbsentError($ErrorRecord,[string[]]$AllowedIds) { $id=[string]$ErrorRecord.FullyQualifiedErrorId;foreach($allowed in $AllowedIds){if($id.StartsWith($allowed+',',[StringComparison]::OrdinalIgnoreCase) -or $id -ceq $allowed){return $true}};$false }
