    }
    elseif ($Spec.Adapter -eq 'Service') { $supplementCheck=Test-WsmServiceSupplement $d.Supplement $s.Supplement -Phase $Phase;foreach($problem in $supplementCheck.Problems){$errors.Add($problem)};if ($s.Configuration.PathName -cne $d.BinaryPathName -or $s.Configuration.DisplayName -cne $d.DisplayName) { $errors.Add('Service binary/display mismatch') };if((ConvertTo-WsmServiceAccount $s.Configuration.StartName) -ine (ConvertTo-WsmServiceAccount $d.Account) -or [string]$s.Configuration.Description -cne [string]$d.Description -or (@($s.Dependencies | Sort-Object) -join ',') -ine (@($d.Dependencies | Sort-Object) -join ',')){$errors.Add('Service account/description/dependencies mismatch')}; if ($Phase -eq 'Staged' -and ($s.Configuration.StartMode -ne 'Disabled' -or $s.State -ne 'Stopped')) { $errors.Add('Service staging invariant violated') } }
    elseif ($Spec.Adapter -eq 'MachineEnvironment') { if ($s.Value -cne [string]$d.Value) { $errors.Add('Environment value mismatch') } }
    elseif ($Spec.Adapter -eq 'TimeZone') {if($Spec.PSObject.Properties['SettingTransition']){if(-not (Test-WsmSettingStateEqual $s $Spec.SettingTransition.After 'TimeZone')){$errors.Add('Time zone or daylight-saving setting mismatch')}}else{$errors.Add('TimeZone requires a reviewed SettingTransition for verification')}}
    elseif ($Spec.Adapter -eq 'SmbShare') {
        if($s.Configuration.Path -ine $d.Path -or $s.Configuration.EncryptData -ne $d.EncryptData -or [string]$s.Configuration.Description -cne [string]$d.Description){$errors.Add('Share configuration mismatch')}
        $expected=@(ConvertTo-WsmShareAclKeys $d.Access);if(($Phase -eq 'Staged' -or -not (Get-WsmDesiredActivation $Spec)) -and -not (Test-WsmDesiredWorldDeny $d)){$expected+=@('S-1-1-0|Deny|Full')};$actual=@(ConvertTo-WsmShareAclKeys $s.Access)
        if((($expected | Sort-Object) -join ';') -cne (($actual | Sort-Object) -join ';')){$errors.Add('Share ACL differs (missing/extra/right/type/principal)')}
    }
    elseif ($Spec.Adapter -eq 'LocalUser') { if ($Phase -eq 'Staged' -and $s.Enabled) { $errors.Add('Local account must remain disabled') }; if ($s.FullName -cne $d.FullName -or $s.Description -cne $d.Description) { $errors.Add('Local user metadata mismatch') } }
    elseif ($Spec.Adapter -eq 'LocalGroup') { if (@(Compare-Object @($d.Members | Sort-Object) @($s.Members | Sort-Object)).Count) { $errors.Add('Group membership mismatch') } }
    elseif ($Spec.Adapter -eq 'Certificate') { if ($s.HasPrivateKey -ne [bool]$d.HasPrivateKey) { $errors.Add('Certificate private key mismatch') } }
    elseif ($Spec.Adapter -eq 'FirewallRule') { if ($Phase -eq 'Staged' -and $s.Enabled -ne 'False') { $errors.Add('Firewall rule must remain disabled') }; if ($s.Rule.Direction -ne $d.Direction -or $s.Rule.Action -ne $d.Action) { $errors.Add('Firewall rule mismatch') };foreach($field in @('LocalPort','RemotePort')){if(@($s.Ports).Count -ne 1 -or (@($s.Ports[0].$field) -join ',') -ine (@($d.$field) -join ',')){$errors.Add('Firewall port/protocol mismatch: '+$field)}};if(@($s.Ports).Count -ne 1 -or (ConvertTo-WsmFirewallProtocol $s.Ports[0].Protocol) -cne (ConvertTo-WsmFirewallProtocol $d.Protocol)){$errors.Add('Firewall protocol mismatch')};foreach($field in @('LocalAddress','RemoteAddress')){if(@($s.Addresses).Count -ne 1 -or (@($s.Addresses[0].$field | Sort-Object) -join ',') -ine (@($d.$field | Sort-Object) -join ',')){$errors.Add('Firewall address mismatch: '+$field)}};if(@($s.Applications).Count -ne 1 -or $s.Applications[0].Program -ine $d.Program){$errors.Add('Firewall program mismatch')};if((@(([string]$s.Rule.Profile).Split(',') | ForEach-Object {$_.Trim()} | Sort-Object) -join ',') -ine (@($d.Profile | ForEach-Object {$_.ToString().Split(',')} | ForEach-Object {$_.Trim()} | Sort-Object) -join ',')){$errors.Add('Firewall profile mismatch')} }
    elseif ($Spec.Adapter -in @('IISPool','IISSite')) { foreach($e in (Test-WsmIisConfiguration $Spec $Phase)){$errors.Add($e)} }
    if($s.Exists -and $d.PSObject.Properties['SecuritySddl']){$actualSddl='';if($Spec.Adapter -eq 'Service'){$actualSddl=Get-WsmServiceSecurity $d.Name}elseif($Spec.Adapter -eq 'ScheduledTask'){$scheduler=New-WsmTaskScheduler;$actualSddl=(Get-WsmTaskSecurityFolderObject $scheduler $d.TaskPath).GetTask($d.TaskName).GetSecurityDescriptor(7)};if((ConvertTo-WsmTaskSecuritySddl $actualSddl) -cne (ConvertTo-WsmTaskSecuritySddl ([string]$d.SecuritySddl))){$errors.Add('Object security descriptor mismatch')}}
    if($s.Exists -and $Spec.Adapter -eq 'ScheduledTask'){try{[void](Assert-WsmTaskSecurityFolders -Folders @($d.FolderSecurity) -OwnedReceipts $OwnedReceipts)}catch{$errors.Add('Task folder security verification failed: '+$_.Exception.GetType().FullName)}}
    if($s.Exists -and $Phase -eq 'Final'){$active=Get-WsmDesiredActivation $Spec;switch($Spec.Adapter){Service{$mode='Disabled';$state='Stopped';if($active){$mode='Manual';if($Spec.DesiredFinalState -eq 'Automatic'){$mode='Auto'};if($Spec.DesiredFinalState -in @('Automatic','Running')){$state='Running'}};if($s.Configuration.StartMode -ne $mode -or $s.State -ne $state){$errors.Add('Service final mode/running state mismatch')}};LocalUser{if($s.Enabled -ne $active){$errors.Add('User final enabled state mismatch')}};FirewallRule{if(($s.Enabled -eq 'True') -ne $active){$errors.Add('Firewall final enabled state mismatch')}};}}
    [pscustomobject]@{Passed=($errors.Count -eq 0); Problems=$errors.ToArray(); Actual=$s; Phase=$Phase}
}
function Get-WsmDesiredActivation($Spec) { $Spec.PSObject.Properties['DesiredFinalState'] -and $Spec.DesiredFinalState -in @('Enabled','Automatic','Manual','Running') }
function ConvertTo-WsmXmlComparable($Node) {
    $attributes=[ordered]@{};foreach($a in @($Node.Attributes | Where-Object {$_.Name -ne 'xmlns' -and $_.Prefix -ne 'xmlns'} | Sort-Object LocalName)){$attributes[$a.LocalName]=$a.Value};$elements=@($Node.ChildNodes | Where-Object NodeType -EQ ([Xml.XmlNodeType]::Element));if($Node.LocalName -notin @('Actions','Triggers')){$elements=@($elements | Sort-Object LocalName)};$children=@(foreach($child in $elements){ConvertTo-WsmXmlComparable $child});$text='';if(-not $elements.Count){$text=$Node.InnerText};([pscustomobject][ordered]@{Name=$Node.LocalName;Attributes=$attributes;Text=$text;Children=$children} | ConvertTo-Json -Compress -Depth 30)
}
function Remove-WsmCreatedAdapter($Spec) {
    $d=$Spec.Desired
    switch($Spec.Adapter){
        ScheduledTask { Unregister-ScheduledTask -TaskName $d.TaskName -TaskPath $d.TaskPath -Confirm:$false }
        Service { $s=Get-CimInstance Win32_Service | Where-Object Name -CEQ $d.Name; if($s.State -ne 'Stopped'){throw 'Stop created service before rollback.'}; $r=Invoke-CimMethod -InputObject $s -MethodName Delete; if($r.ReturnValue -ne 0){throw ('Service delete native code '+$r.ReturnValue)} }
        SmbShare { Remove-SmbShare -Name $d.Name -ScopeName '*' -Force }
        MachineEnvironment { [Environment]::SetEnvironmentVariable($d.Name,$null,'Machine') }
        TimeZone { throw 'TimeZone cannot be removed; restore a reviewed prior state through SettingTransition rollback.' }
        WindowsFeature { throw 'Feature removal requires explicit dedicated rollback; dependency/reboot effects must be reviewed.' }
        LocalUser { Remove-LocalUser -Name $d.Name }
        LocalGroup { Remove-LocalGroup -Name $d.Name }
        FirewallRule { Remove-NetFirewallRule -Name $d.Name }
        Certificate { Remove-Item -LiteralPath ($d.Store+'\'+$d.Thumbprint) }
        { $_ -in @('IISPool','IISSite') } { Remove-WsmIisObject $Spec }
    }
}

function ConvertTo-WsmFirewallProtocol([string]$Value){switch($Value.ToUpperInvariant()){TCP{'6'};UDP{'17'};ICMPV4{'1'};ICMPV6{'58'};ANY{'256'};default{$Value}}}

function Get-WsmServiceDependencies([string]$Name){$p=Get-ItemProperty -LiteralPath ('HKLM:\SYSTEM\CurrentControlSet\Services\'+$Name);if($p.PSObject.Properties['DependOnService']){@($p.DependOnService)};if($p.PSObject.Properties['DependOnGroup']){foreach($group in @($p.DependOnGroup)){if([string]::IsNullOrWhiteSpace($group)){throw 'Empty source service dependency group.'};'+'+[string]$group}}}
function ConvertTo-WsmServiceAccount([string]$Name){switch -Regex ($Name){'^(?i:LocalSystem|NT AUTHORITY\\SYSTEM|SYSTEM|S-1-5-18)$'{'LocalSystem';break};'^(?i:LocalService|NT AUTHORITY\\LocalService|S-1-5-19)$'{'NT AUTHORITY\LocalService';break};'^(?i:NetworkService|NT AUTHORITY\\NetworkService|S-1-5-20)$'{'NT AUTHORITY\NetworkService';break};default{$Name}}}
